<?php
require __DIR__ . '/_guard.php';
chatweb_admin_require_permission($conn, 'system.view');
$calls = mysqli_query($conn, "SELECT cs.*, cu.full_name caller, ru.full_name receiver FROM call_sessions cs LEFT JOIN users cu ON cu.id=cs.caller_id LEFT JOIN users ru ON ru.id=cs.receiver_id ORDER BY cs.id DESC LIMIT 100");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Calls | Chat Web Admin</title><style>body{margin:0;background:#f7f7f8;font-family:Arial,sans-serif;color:#172033}.main{padding:30px}.panel{background:#fff;border-radius:10px;padding:22px;box-shadow:0 13px 30px rgba(15,23,42,.05);overflow:auto}a{color:#e6a300;text-decoration:none;font-weight:800}table{width:100%;border-collapse:collapse;min-width:860px}th{background:#f0f0f1}th,td{text-align:left;padding:14px;border-bottom:1px solid #e5e7eb}</style></head><body><main class="main"><a href="index.php">Dashboard</a><h1>Calls</h1><section class="panel"><table><thead><tr><th>ID</th><th>Type</th><th>Status</th><th>Caller</th><th>Receiver</th><th>Created</th></tr></thead><tbody><?php while($row=mysqli_fetch_assoc($calls)){ ?><tr><td>#<?php echo (int)$row['id']; ?></td><td><?php echo htmlspecialchars($row['call_type']); ?></td><td><?php echo htmlspecialchars($row['status']); ?></td><td><?php echo htmlspecialchars($row['caller'] ?: $row['caller_id']); ?></td><td><?php echo htmlspecialchars($row['receiver'] ?: $row['receiver_id']); ?></td><td><?php echo htmlspecialchars($row['created_at']); ?></td></tr><?php } ?></tbody></table></section></main></body></html>
